import * as React from 'react';
import Box from '@mui/material/Box';
import Button from '@mui/material/Button';
import CssBaseline from '@mui/material/CssBaseline';
import IconButton from '@mui/material/IconButton';
import InputLabel from '@mui/material/InputLabel';
import Link from '@mui/material/Link';
import Paper from '@mui/material/Paper';
import Snackbar from '@mui/material/Snackbar';
import TextField from '@mui/material/TextField';
import VideocamOutlinedIcon from '@mui/icons-material/VideocamOutlined';
import ArrowForwardIcon from '@mui/icons-material/ArrowForward';
import { createTheme, ThemeProvider } from '@mui/material/styles';
import { AuthContext } from '../contexts/AuthContext';

const defaultTheme = createTheme();

export default function Authentication() {
  const [username, setUsername] = React.useState('');
  const [password, setPassword] = React.useState('');
  const [name, setName] = React.useState('');
  const [error, setError] = React.useState('');
  const [message, setMessage] = React.useState('');

  const [formState, setFormState] = React.useState(0);

  const [open, setOpen] = React.useState(false);

  const { handleRegister, handleLogin } = React.useContext(AuthContext);

  const handleAuth = async () => {
    try {
      if (formState === 0) {
        await handleLogin(username, password);
      }

      if (formState === 1) {
        const result = await handleRegister(name, username, password);
        setUsername('');
        setMessage(result);
        setOpen(true);
        setError('');
        setFormState(0);
        setPassword('');
      }
    } catch (err) {
      const currentMessage = err?.response?.data?.message || 'Something went wrong';
      setError(currentMessage);
    }
  };

  const title = formState === 0 ? 'Join Meeting' : 'Host Meeting';
  const subtitle =
    formState === 0
      ? 'Enter the code to join the room.'
      : 'Create your account to host a room.';

  return (
    <ThemeProvider theme={defaultTheme}>
      <CssBaseline />
      <Box
        sx={{
          minHeight: '100vh',
          bgcolor: '#eef2f8',
          display: 'flex',
          alignItems: 'center',
          justifyContent: 'center',
          px: 2,
          py: 4,
        }}
      >
        <Paper
          elevation={0}
          sx={{
            width: '100%',
            maxWidth: 540,
            borderRadius: '32px',
            border: '1px solid #d4dbe8',
            boxShadow: '0 16px 34px rgba(15, 23, 42, 0.10)',
            bgcolor: '#f8fafc',
            px: { xs: 3, sm: 5 },
            py: { xs: 4, sm: 5 },
          }}
        >
          <Box sx={{ display: 'flex', justifyContent: 'center', mb: 3 }}>
            <IconButton
              disableRipple
              sx={{
                width: 74,
                height: 74,
                borderRadius: '20px',
                color: '#ffffff',
                bgcolor: '#3d66e7',
                '&:hover': {
                  bgcolor: '#3d66e7',
                },
                boxShadow: '0 10px 20px rgba(61, 102, 231, 0.35)',
              }}
            >
              <VideocamOutlinedIcon sx={{ fontSize: 36 }} />
            </IconButton>
          </Box>

          <Box sx={{ textAlign: 'center', mb: 4 }}>
            <Box
              component="h1"
              sx={{
                m: 0,
                color: '#0f172a',
                fontWeight: 700,
                letterSpacing: '-0.6px',
                fontSize: { xs: '48px', sm: '54px' },
                lineHeight: 1.1,
              }}
            >
              {title}
            </Box>
            <Box
              component="p"
              sx={{
                m: '12px 0 0',
                color: '#64748b',
                fontSize: '14px',
                fontWeight: 500,
              }}
            >
              {subtitle}
            </Box>
          </Box>

          <Box component="form" noValidate>
            {formState === 1 && (
              <Box sx={{ mb: 3 }}>
                <InputLabel
                  htmlFor="full-name"
                  sx={{ mb: 1, color: '#334155', fontSize: '16px', fontWeight: 700 }}
                >
                  Full Name
                </InputLabel>
                <TextField
                  id="full-name"
                  required
                  fullWidth
                  value={name}
                  placeholder="Full Name"
                  onChange={(e) => setName(e.target.value)}
                  InputProps={{
                    sx: {
                      borderRadius: '16px',
                      bgcolor: '#f1f5f9',
                      height: 64,
                      fontSize: '16px',
                      color: '#334155',
                      '& input::placeholder': {
                        color: '#90a0b7',
                        opacity: 1,
                      },
                    },
                  }}
                />
              </Box>
            )}

            <Box sx={{ mb: 3 }}>
              <InputLabel
                htmlFor="username"
                sx={{ mb: 1, color: '#334155', fontSize: '16px', fontWeight: 700 }}
              >
                {formState === 0 ? 'Your Name' : 'Username'}
              </InputLabel>
              <TextField
                id="username"
                required
                fullWidth
                value={username}
                placeholder={formState === 0 ? 'Full Name' : 'Username'}
                onChange={(e) => setUsername(e.target.value)}
                InputProps={{
                  sx: {
                    borderRadius: '16px',
                    bgcolor: '#f1f5f9',
                    height: 64,
                    fontSize: '16px',
                    color: '#334155',
                    '& input::placeholder': {
                      color: '#90a0b7',
                      opacity: 1,
                    },
                  },
                }}
              />
            </Box>

            <Box sx={{ mb: 3 }}>
              <InputLabel
                htmlFor="password"
                sx={{ mb: 1, color: '#334155', fontSize: '16px', fontWeight: 700 }}
              >
                {formState === 0 ? 'Meeting Code' : 'Password'}
              </InputLabel>
              <TextField
                id="password"
                required
                fullWidth
                value={password}
                placeholder={formState === 0 ? 'abc-123-xyz' : 'Password'}
                type={formState === 0 ? 'text' : 'password'}
                onChange={(e) => setPassword(e.target.value)}
                InputProps={{
                  sx: {
                    borderRadius: '16px',
                    bgcolor: '#f1f5f9',
                    height: 64,
                    fontSize: '16px',
                    color: '#334155',
                    '& input::placeholder': {
                      color: '#90a0b7',
                      opacity: 1,
                    },
                  },
                }}
              />
            </Box>

            {error ? (
              <Box sx={{ mb: 2, color: '#dc2626', fontSize: '14px', fontWeight: 600 }}>
                {error}
              </Box>
            ) : null}

            <Button
              type="button"
              fullWidth
              variant="contained"
              onClick={handleAuth}
              endIcon={<ArrowForwardIcon />}
              sx={{
                mt: 1,
                height: 64,
                borderRadius: '16px',
                textTransform: 'none',
                fontWeight: 800,
                fontSize: '18px',
                color: '#ffffff',
                background: 'linear-gradient(135deg, #8ea5e3 0%, #8299dc 100%)',
                boxShadow: '0 8px 18px rgba(130, 153, 220, 0.3)',
                '&:hover': {
                  background: 'linear-gradient(135deg, #8199db 0%, #748dd2 100%)',
                },
              }}
            >
              {formState === 0 ? 'Join Now' : 'Create Account'}
            </Button>

            <Box sx={{ mt: 4, textAlign: 'center' }}>
              <Link
                component="button"
                type="button"
                onClick={() => {
                  setFormState((current) => (current === 0 ? 1 : 0));
                  setError('');
                }}
                underline="hover"
                sx={{
                  fontWeight: 700,
                  color: '#2e5fe0',
                  fontSize: '18px',
                  textDecorationColor: 'transparent',
                  '&:hover': {
                    textDecorationColor: '#2e5fe0',
                  },
                }}
              >
                {formState === 0 ? 'Host a meeting instead?' : 'Join a meeting instead?'}
              </Link>
            </Box>
          </Box>
        </Paper>
      </Box>

      <Snackbar open={open} autoHideDuration={4000} message={message} />
    </ThemeProvider>
  );
}
